import{_ as t,a0 as l,w as r,s as o,I as n,x as a,a1 as p,A as i,ao as d}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const v=JSON.parse('{"title":"在 Linux 上使用开源软件创建 SDN | LCTT x X-CMD","titleTemplate":false,"description":"在 Linux 上使用开源软件创建 SDN | LCTT (202005) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在 Linux 上使用开源软件创建 SDN | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在 Linux 上使用开源软件创建 SDN | LCTT (202005) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202005/20200417 Create a SDN on Linux with open source","title":"在 Linux 上使用开源软件创建 SDN","tag":"202005","desc":""},"relativePath":"202005/20200417 Create a SDN on Linux with open source.md","filePath":"[post].md"}'),g={name:"202005/20200417 Create a SDN on Linux with open source.md"};function u(h,s,c,f,k,b){const e=l("Link");return r(),o("div",null,[s[26]||(s[26]=n("h1",{id:"在-linux-上使用开源软件创建-sdn",tabindex:"-1"},[a("在 Linux 上使用开源软件创建 SDN "),n("a",{class:"header-anchor",href:"#在-linux-上使用开源软件创建-sdn","aria-label":"Permalink to “在 Linux 上使用开源软件创建 SDN”"},"​")],-1)),s[27]||(s[27]=n("blockquote",null,[n("p",null,"使用开源路由协议栈 Quagga，使你的 Linux 系统成为一台路由器。")],-1)),s[28]||(s[28]=n("p",null,[n("img",{src:"https://img.linux.net.cn/data/attachment/album/202005/09/093541rqx3zr5dxn3yvnq6.jpg",alt:""})],-1)),n("p",null,[s[1]||(s[1]=a("网络路由协议分为两大类：内部网关协议和外部网关协议。路由器使用内部网关协议在单个自治系统内共享信息。如果你用的是 Linux，则可以通过开源（GPLv2）路由协议栈 ",-1)),p(e,{href:"https://www.quagga.net/"},{default:i(()=>[...s[0]||(s[0]=[a("Quagga",-1)])]),_:1}),s[2]||(s[2]=a(" 使其表现得像一台路由器。",-1))]),s[29]||(s[29]=n("h3",{id:"quagga-是什么",tabindex:"-1"},[a("Quagga 是什么？ "),n("a",{class:"header-anchor",href:"#quagga-是什么","aria-label":"Permalink to “Quagga 是什么？”"},"​")],-1)),n("p",null,[s[5]||(s[5]=a("Quagga 是一个",-1)),p(e,{href:"https://en.wikipedia.org/wiki/Quagga_(software)"},{default:i(()=>[...s[3]||(s[3]=[a("路由软件包",-1)])]),_:1}),s[6]||(s[6]=a("，并且是 ",-1)),p(e,{href:"https://www.gnu.org/software/zebra/"},{default:i(()=>[...s[4]||(s[4]=[a("GNU Zebra",-1)])]),_:1}),s[7]||(s[7]=a(" 的一个分支。它为类 Unix 平台提供了所有主流路由协议的实现，例如开放最短路径优先（OSPF），路由信息协议（RIP），边界网关协议（BGP）和中间系统到中间系统协议（IS-IS）。",-1))]),s[30]||(s[30]=n("p",null,"尽管 Quagga 实现了 IPv4 和 IPv6 的路由协议，但它并不是一个完整的路由器。一个真正的路由器不仅实现了所有路由协议，而且还有转发网络流量的能力。 Quagga 仅仅实现了路由协议栈，而转发网络流量的工作由 Linux 内核处理。",-1)),s[31]||(s[31]=n("h3",{id:"架构",tabindex:"-1"},[a("架构 "),n("a",{class:"header-anchor",href:"#架构","aria-label":"Permalink to “架构”"},"​")],-1)),n("p",null,[s[9]||(s[9]=a("Quagga 通过特定协议的守护程序实现不同的路由协议。守护程序名称与路由协议相同，加了字母“d”作为后缀。Zebra 是核心，也是与协议无关的守护进程，它为内核提供了一个",-1)),p(e,{href:"https://en.wikipedia.org/wiki/Abstraction_layer"},{default:i(()=>[...s[8]||(s[8]=[a("抽象层",-1)])]),_:1}),s[10]||(s[10]=a("，并通过 TCP 套接字向 Quagga 客户端提供 Zserv API。每个特定协议的守护程序负责运行相关的协议，并基于交换的信息来建立路由表。",-1))]),s[32]||(s[32]=d(`<p><img src="https://opensource.com/sites/default/files/uploads/quagga_arch.png" alt="Quagga architecture" title="Quagga architecture"></p><h3 id="环境" tabindex="-1">环境 <a class="header-anchor" href="#环境" aria-label="Permalink to “环境”">​</a></h3><p>本教程通过 Quagga 实现的 OSPF 协议来配置动态路由。该环境包括两个名为 Alpha 和 Beta 的 CentOS 7.7 主机。两台主机共享访问 <strong>192.168.122.0/24</strong> 网络。</p><p><strong>主机 Alpha：</strong></p><p>IP：192.168.122.100/24 网关：192.168.122.1</p><p><strong>主机 Beta：</strong></p><p>IP：192.168.122.50/24 网关：192.168.122.1</p><h3 id="安装软件包" tabindex="-1">安装软件包 <a class="header-anchor" href="#安装软件包" aria-label="Permalink to “安装软件包”">​</a></h3><p>首先，在两台主机上安装 Quagga 软件包。它存在于 CentOS 基础仓库中：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>yum install quagga -y</span></span></code></pre></div><h3 id="启用-ip-转发" tabindex="-1">启用 IP 转发 <a class="header-anchor" href="#启用-ip-转发" aria-label="Permalink to “启用 IP 转发”">​</a></h3><p>接下来，在两台主机上启用 IP 转发，因为它将由 Linux 内核来执行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sysctl -w net.ipv4.ip_forward = 1</span></span>
<span class="line"><span>sysctl -p</span></span></code></pre></div><h3 id="配置" tabindex="-1">配置 <a class="header-anchor" href="#配置" aria-label="Permalink to “配置”">​</a></h3><p>现在，进入 <code>/etc/quagga</code> 目录并为你的设置创建配置文件。你需要三个文件：</p><ul><li><code>zebra.conf</code>：Quagga 守护程序的配置文件，你可以在其中定义接口及其 IP 地址和 IP 转发</li><li><code>ospfd.conf</code>：协议配置文件，你可以在其中定义将通过 OSPF 协议提供的网络</li><li><code>daemons</code>：你将在其中指定需要运行的相关的协议守护程序</li></ul><p>在主机 Alpha 上，</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span> [root@alpha]# cat /etc/quagga/zebra.conf</span></span>
<span class="line"><span>interface eth0</span></span>
<span class="line"><span> ip address 192.168.122.100/24</span></span>
<span class="line"><span> ipv6 nd suppress-ra</span></span>
<span class="line"><span>interface eth1</span></span>
<span class="line"><span> ip address 10.12.13.1/24</span></span>
<span class="line"><span> ipv6 nd suppress-ra</span></span>
<span class="line"><span>interface lo</span></span>
<span class="line"><span>ip forwarding</span></span>
<span class="line"><span>line vty</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[root@alpha]# cat /etc/quagga/ospfd.conf</span></span>
<span class="line"><span>interface eth0</span></span>
<span class="line"><span>interface eth1</span></span>
<span class="line"><span>interface lo</span></span>
<span class="line"><span>router ospf</span></span>
<span class="line"><span> network 192.168.122.0/24 area 0.0.0.0</span></span>
<span class="line"><span> network 10.12.13.0/24 area 0.0.0.0</span></span>
<span class="line"><span>line vty</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[root@alphaa ~]# cat /etc/quagga/daemons</span></span>
<span class="line"><span>zebra=yes</span></span>
<span class="line"><span>ospfd=yes</span></span></code></pre></div><p>在主机 Beta 上，</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@beta quagga]# cat zebra.conf</span></span>
<span class="line"><span>interface eth0</span></span>
<span class="line"><span> ip address 192.168.122.50/24</span></span>
<span class="line"><span> ipv6 nd suppress-ra</span></span>
<span class="line"><span>interface eth1</span></span>
<span class="line"><span> ip address 10.10.10.1/24</span></span>
<span class="line"><span> ipv6 nd suppress-ra</span></span>
<span class="line"><span>interface lo</span></span>
<span class="line"><span>ip forwarding</span></span>
<span class="line"><span>line vty</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[root@beta quagga]# cat ospfd.conf</span></span>
<span class="line"><span>interface eth0</span></span>
<span class="line"><span>interface eth1</span></span>
<span class="line"><span>interface lo</span></span>
<span class="line"><span>router ospf</span></span>
<span class="line"><span> network 192.168.122.0/24 area 0.0.0.0</span></span>
<span class="line"><span> network 10.10.10.0/24 area 0.0.0.0</span></span>
<span class="line"><span>line vty</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[root@beta ~]# cat /etc/quagga/daemons</span></span>
<span class="line"><span>zebra=yes</span></span>
<span class="line"><span>ospfd=yes</span></span></code></pre></div><h3 id="配置防火墙" tabindex="-1">配置防火墙 <a class="header-anchor" href="#配置防火墙" aria-label="Permalink to “配置防火墙”">​</a></h3><p>要使用 OSPF 协议，必须允许它通过防火墙：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>firewall-cmd --add-protocol=ospf –permanent</span></span>
<span class="line"><span></span></span>
<span class="line"><span>firewall-cmd –reload</span></span></code></pre></div><p>现在，启动 <code>zebra</code> 和 <code>ospfd</code> 守护程序。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># systemctl start zebra</span></span>
<span class="line"><span># systemctl start ospfd</span></span></code></pre></div><p>用下面命令在两个主机上查看路由表:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@alpha ~]# ip route show  </span></span>
<span class="line"><span>default via 192.168.122.1 dev eth0 proto static metric 100</span></span>
<span class="line"><span>10.10.10.0/24 via 192.168.122.50 dev eth0 proto zebra metric 20</span></span>
<span class="line"><span>10.12.13.0/24 dev eth1 proto kernel scope link src 10.12.13.1</span></span>
<span class="line"><span>192.168.122.0/24 dev eth0 proto kernel scope link src 192.168.122.100 metric 100</span></span></code></pre></div><p>你可以看到 Alpha 上的路由表包含通过 <strong>192.168.122.50</strong> 到达 <strong>10.10.10.0/24</strong> 的路由项，它是通过协议 zebra 获取的。同样，在主机 Beta 上，该表包含通过 <strong>192.168.122.100</strong> 到达网络 <strong>10.12.13.0/24</strong> 的路由项。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@beta ~]# ip route show</span></span>
<span class="line"><span>default via 192.168.122.1 dev eth0 proto static metric 100</span></span>
<span class="line"><span>10.10.10.0/24 dev eth1 proto kernel scope link src 10.10.10.1</span></span>
<span class="line"><span>10.12.13.0/24 via 192.168.122.100 dev eth0 proto zebra metric 20</span></span>
<span class="line"><span>192.168.122.0/24 dev eth0 proto kernel scope link src 192.168.122.50 metric 100</span></span></code></pre></div><h3 id="结论" tabindex="-1">结论 <a class="header-anchor" href="#结论" aria-label="Permalink to “结论”">​</a></h3><p>如你所见，环境和配置相对简单。要增加复杂性，你可以向路由器添加更多网络接口，以为更多网络提供路由。你也可以使用相同的方法来实现 BGP 和 RIP 协议。</p><hr>`,32)),n("p",null,[s[12]||(s[12]=a("via: ",-1)),p(e,{href:"https://opensource.com/article/20/4/quagga-linux"},{default:i(()=>[...s[11]||(s[11]=[a("https://opensource.com/article/20/4/quagga-linux",-1)])]),_:1})]),n("p",null,[s[17]||(s[17]=a("作者：",-1)),p(e,{href:"https://opensource.com/users/noisybotnet"},{default:i(()=>[...s[13]||(s[13]=[a("M Umer",-1)])]),_:1}),s[18]||(s[18]=a(" 选题：",-1)),p(e,{href:"https://github.com/lujun9972"},{default:i(()=>[...s[14]||(s[14]=[a("lujun9972",-1)])]),_:1}),s[19]||(s[19]=a(" 译者：",-1)),p(e,{href:"https://github.com/messon007"},{default:i(()=>[...s[15]||(s[15]=[a("messon007",-1)])]),_:1}),s[20]||(s[20]=a(" 校对：",-1)),p(e,{href:"https://github.com/wxy"},{default:i(()=>[...s[16]||(s[16]=[a("wxy",-1)])]),_:1})]),n("p",null,[s[23]||(s[23]=a("本文由 ",-1)),p(e,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...s[21]||(s[21]=[a("LCTT",-1)])]),_:1}),s[24]||(s[24]=a(" 原创编译，",-1)),p(e,{href:"https://linux.cn/"},{default:i(()=>[...s[22]||(s[22]=[a("Linux中国",-1)])]),_:1}),s[25]||(s[25]=a(" 荣誉推出",-1))])])}const y=t(g,[["render",u]]);export{v as __pageData,y as default};
